function buildControlStates(eventsByCandidate){const out=new Map();for(const [candidateId,events] of eventsByCandidate){const s={candidateId,status:'PENDING_FORWARD_ENTRY',entry:null,initialStop:null,targets:[],entryCandleOpenAt:null,entryCandleCloseAt:null,expiryCandleOpenAt:null,expiryCandleCloseAt:null,legs:{R1:{status:'OPEN'},R2:{status:'OPEN'},R5:{status:'OPEN'}}};for(const e of events){if(e.type==='CANDIDATE_ENTRY_EXPIRED'){s.status='EXPIRED';s.expiryReason=e.reason;s.expiryCandleOpenAt=e.candleOpenAt;s.expiryCandleCloseAt=e.candleCloseAt;}else if(e.type==='CANDIDATE_FORWARD_ENTRY_OPENED'){s.status='OPEN_PAPER';s.entry=e.entry;s.initialStop=e.initialStop;s.targets=e.targets||[];s.entryCandleOpenAt=e.entryCandleOpenAt;s.entryCandleCloseAt=e.entryCandleCloseAt;for(const rr of RR_LEGS)s.legs[`R${rr}`]={status:'OPEN',target:s.targets.find(x=>Number(x.rr)===rr)?.target,currentStop:s.initialStop,stopStage:'INITIAL'};}else if(e.type==='STOP_MOVED_TO_BREAKEVEN'||e.type==='STOP_MOVED_TO_HALF_TARGET'){const k=`R${e.rr}`,leg=s.legs[k]||{};leg.currentStop=e.newStop;leg.stopStage=e.type==='STOP_MOVED_TO_BREAKEVEN'?'BREAKEVEN':'HALF_TARGET_LOCK';s.legs[k]=leg;}else if(['LEG_TARGET_HIT','LEG_STOP_HIT','LEG_CLOSED_AMBIGUOUS'].includes(e.type)){const k=`R${e.rr}`,leg=s.legs[k]||{};leg.status=e.type==='LEG_TARGET_HIT'?'TARGET_HIT':e.type==='LEG_STOP_HIT'?'STOP_HIT':'AMBIGUOUS';leg.resultR=e.type==='LEG_CLOSED_AMBIGUOUS'?null:e.resultR;leg.exitPrice=e.exitPrice??null;leg.closeReason=e.type==='LEG_STOP_HIT'?`STOP_HIT_${e.stopStage||leg.stopStage||'INITIAL'}`:e.type==='LEG_TARGET_HIT'?'TARGET_HIT':'AMBIGUOUS_BOTH_STOP_AND_TARGET_TOUCHED';leg.exitCandleOpenAt=e.candleOpenAt;leg.exitCandleCloseAt=e.candleCloseAt;s.legs[k]=leg;}else if(e.type==='CANDIDATE_CLOSED')s.status='CLOSED_PAPER';}out.set(candidateId,s);}return out;}
function compareControl(sim,control){
  const reasons=[];
  if(!control)return{status:'UNKNOWN_CONTROL_STATE',reasons:['CONTROL_CANDIDATE_NOT_IN_LEDGER_FOLD']};
  const simEntry=sim.entryStatus;
  if(control.status==='PENDING_FORWARD_ENTRY'&&simEntry!=='PENDING')reasons.push('ENTRY_STATUS_DIVERGENCE');
  if(control.status==='EXPIRED'&&simEntry!=='EXPIRED')reasons.push('ENTRY_STATUS_DIVERGENCE');
  if(['OPEN_PAPER','CLOSED_PAPER'].includes(control.status)&&simEntry!=='ENTERED')reasons.push('ENTRY_STATUS_DIVERGENCE');
  if(simEntry==='EXPIRED'&&control.status==='EXPIRED'){
    if(sim.expiryCandleOpenAt!==control.expiryCandleOpenAt)reasons.push('EXPIRY_CANDLE_OPEN_DIVERGENCE');
    if(sim.expiryCandleCloseAt!==control.expiryCandleCloseAt)reasons.push('EXPIRY_CANDLE_CLOSE_DIVERGENCE');
    if(control.expiryReason&&sim.expiryReason&&control.expiryReason!==sim.expiryReason)reasons.push('EXPIRY_REASON_DIVERGENCE');
  }
  if(simEntry==='ENTERED'&&['OPEN_PAPER','CLOSED_PAPER'].includes(control.status)){
    if(roundPrice(sim.entry)!==roundPrice(control.entry))reasons.push('ENTRY_PRICE_DIVERGENCE');
    if(roundPrice(sim.initialStop)!==roundPrice(control.initialStop))reasons.push('INITIAL_STOP_DIVERGENCE');
    if(sim.entryCandleOpenAt!==control.entryCandleOpenAt)reasons.push('ENTRY_CANDLE_OPEN_DIVERGENCE');
    if(sim.entryCandleCloseAt!==control.entryCandleCloseAt)reasons.push('ENTRY_CANDLE_CLOSE_DIVERGENCE');
    for(const rr of RR_LEGS){
      const a=sim.legs[`R${rr}`],b=control.legs[`R${rr}`];
      if(!a||!b){reasons.push(`R${rr}_LEG_STATE_MISSING`);continue;}
      if(economicLegSignature(a)!==economicLegSignature(b))reasons.push(`R${rr}_ECONOMIC_OR_CANDLE_STATE_DIVERGENCE`);
    }
  }
  return{status:reasons.length?'CONTROL_PARITY_DIVERGENCE':'PASS',reasons:unique(reasons)};
}

